const burger=document.getElementById("burger"),nav=document.getElementById("nav"),body=document.body;if(burger&&nav){burger.addEventListener("click",()=>{burger.classList.toggle("active"),nav.classList.toggle("active"),body.classList.toggle("menu-open")});const navLinks=nav.querySelectorAll(".nav-link");navLinks.forEach(link=>{link.addEventListener("click",()=>{burger.classList.remove("active"),nav.classList.remove("active"),body.classList.remove("menu-open")})}),document.addEventListener("click",e=>{!nav.contains(e.target)&&!burger.contains(e.target)&&nav.classList.contains("active")&&(burger.classList.remove("active"),nav.classList.remove("active"),body.classList.remove("menu-open"))})}const header=document.getElementById("header");let lastScroll=0;window.addEventListener("scroll",()=>{const currentScroll=window.pageYOffset;currentScroll>100?header.classList.add("scrolled"):header.classList.remove("scrolled"),lastScroll=currentScroll});const faqItems=document.querySelectorAll(".faq-item");faqItems.forEach(item=>{const question=item.querySelector(".faq-question");question.addEventListener("click",()=>{const isActive=item.classList.contains("active");faqItems.forEach(otherItem=>{otherItem.classList.remove("active")}),isActive||item.classList.add("active")})});document.querySelectorAll('a[href^="#"]').forEach(anchor=>{anchor.addEventListener("click",function(e){const targetId=this.getAttribute("href");if("#"===targetId||"#register"===targetId||"#contact"===targetId||"#chat"===targetId||"#terms"===targetId||"#privacy"===targetId||"#responsible"===targetId)return;const target=document.querySelector(targetId);if(target){e.preventDefault();const headerHeight=header?header.offsetHeight:0,targetPosition=target.getBoundingClientRect().top+window.pageYOffset-headerHeight-20;window.scrollTo({top:targetPosition,behavior:"smooth"})}})});const observerOptions={threshold:.1,rootMargin:"0px 0px -100px 0px"},observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{entry.isIntersecting&&(entry.target.style.opacity="1",entry.target.style.transform="translateY(0)")})},observerOptions),cards=document.querySelectorAll(".fact-card, .step-card, .game-category, .advantage-card, .review-card");cards.forEach(card=>{card.style.opacity="0",card.style.transform="translateY(30px)",card.style.transition="opacity 0.6s ease, transform 0.6s ease",observer.observe(card)});if("loading"in HTMLImageElement.prototype){const images=document.querySelectorAll('img[loading="lazy"]');images.forEach(img=>{img.src=img.dataset.src||img.src})}else{const lazyImages=document.querySelectorAll('img[loading="lazy"]'),imageObserver=new IntersectionObserver((entries,observer)=>{entries.forEach(entry=>{if(entry.isIntersecting){const img=entry.target;img.src=img.dataset.src||img.src,img.classList.add("loaded"),observer.unobserve(img)}})});lazyImages.forEach(img=>imageObserver.observe(img))}console.log("Dragonia Casino - Website Loaded Successfully");